def max_dot_product(nums1, nums2):
    n, m = len(nums1), len(nums2)
    best = float('-inf')
    from itertools import combinations
    for r in range(1, min(n, m) + 1):
        for idx1 in combinations(range(n), r):
            for idx2 in combinations(range(m), r):
                total = sum(nums1[a] * nums2[b] for a, b in zip(idx1, idx2))   # pair up chosen positions in order, multiply and sum directly
                best = max(best, total)
    return best


if __name__ == "__main__":
    print(max_dot_product([2, 1, -2, 5], [3, 0, -6]))

