import java.util.*;

public class Main {
    int maxDotProduct(int[] nums1, int[] nums2) {
        int n = nums1.length, m = nums2.length;
        int best = Integer.MIN_VALUE;
        // Conceptually: try every pair of equal-length subsequences (one from each array)
        // and every valid pairing between their positions, computing the dot product directly.
        // (Enumerating all subsequence pairs is exponential; shown here for illustration only.)
        for (int mask1 = 1; mask1 < (1 << n); mask1++) {
            for (int mask2 = 1; mask2 < (1 << m); mask2++) {
                if (Integer.bitCount(mask1) != Integer.bitCount(mask2)) continue;   // subsequences must be the same length
                List<Integer> a = new ArrayList<>(), b = new ArrayList<>();
                for (int i = 0; i < n; i++) if ((mask1 & (1 << i)) != 0) a.add(nums1[i]);
                for (int j = 0; j < m; j++) if ((mask2 & (1 << j)) != 0) b.add(nums2[j]);
                int total = 0;
                for (int k = 0; k < a.size(); k++) total += a.get(k) * b.get(k);      // pair up chosen positions in order, multiply and sum directly
                best = Math.max(best, total);
            }
        }
        return best;
    }

    public static void main(String[] args) {
        Main solution = new Main();
        System.out.println(solution.maxDotProduct(new int[]{2, 1, -2, 5}, new int[]{3, 0, -6}));
    }
}

