using namespace std;

int maxDotProduct(vector<int>& nums1, vector<int>& nums2) {
    int n = (int)nums1.size(), m = (int)nums2.size();
    int best = INT_MIN;
    for (int mask1 = 1; mask1 < (1 << n); mask1++) {
        for (int mask2 = 1; mask2 < (1 << m); mask2++) {
            if (__builtin_popcount(mask1) != __builtin_popcount(mask2)) continue;   // subsequences must be the same length
            vector<int> a, b;
            for (int i = 0; i < n; i++) if (mask1 & (1 << i)) a.push_back(nums1[i]);
            for (int j = 0; j < m; j++) if (mask2 & (1 << j)) b.push_back(nums2[j]);
            int total = 0;
            for (int k = 0; k < (int)a.size(); k++) total += a[k] * b[k];             // pair up chosen positions in order, multiply and sum directly
            best = max(best, total);
        }
    }
    return best;
}

