def max_dot_product(nums1, nums2):
    n, m = len(nums1), len(nums2)
    NEG_INF = float('-inf')
    dp = [[NEG_INF] * (m + 1) for _ in range(n + 1)]                        # dp[i][j] = best dot product using a non-empty match within nums1[:i], nums2[:j]
    for i in range(1, n + 1):
        for j in range(1, m + 1):
            prod = nums1[i - 1] * nums2[j - 1]
            extend = max(dp[i - 1][j - 1], 0) + prod                       # extend a positive prior streak, or start fresh here if the prior streak wasn't worth keeping
            dp[i][j] = max(extend, dp[i - 1][j], dp[i][j - 1])             # or skip either the current nums1 or nums2 element entirely
    return dp[n][m]


if __name__ == "__main__":
    print(max_dot_product([2, 1, -2, 5], [3, 0, -6]))

